import assert from "node:assert/strict";
import { appendFileSync } from "node:fs";
import { createInterface } from "node:readline";
import { buildChoice } from "./build-choice";
import { fightNative, hash } from "./native";
import { SearchDriver } from "./sources/common/src/simulation/search_driver";
import { selectBarrelForecastIntent } from "./sources/common/src/simulation/barrel_forecast_intent_research";
import { permuteRankedDraftSeed } from "./sources/common/src/simulation/ranked_draft_eval";
import { getA19NeuralModel } from "./sources/common/src/simulation/a19_neural_model";
import { loadLockedA19FullPolicyPair } from "./sources/common/src/simulation/v0_9/a19_full_policy_checkpoint";

const [output] = process.argv.slice(2), g = globalThis as any;
const proto = SearchDriver.prototype as any;
const choose = proto.chooseDecision, rollout = proto.rollout;
const model = getA19NeuralModel(), predict = model.predict, accepted = loadLockedA19FullPolicyPair();
let scope: any;
model.predict = (observation: any) => {
    if (g.__mode === "accepted" && g.__modelActorTeam === g.__team) {
        g.__acceptedCalls++;
        return accepted.predict(observation);
    }
    return predict.call(model, observation);
};
proto.chooseDecision = function (unit: any, ...args: any[]) {
    g.__modelActorTeam = unit.getTeam();
    const result = choose.call(this, unit, ...args);
    assert(!g.__forecastFault, `Forecast callback failed: ${g.__forecastFault}`);
    return result;
};
proto.rollout = function (unit: any, candidate: any, ...args: any[]) {
    const prior = scope;
    scope = g.__mode !== "stock" && g.__mode !== "accepted" && unit.getTeam() === g.__team
        ? { rootTeam: unit.getTeam(), rootActor: unit.getName(), mode: args[2], candidateKind: candidate.kind }
        : undefined;
    try {
        const value = rollout.call(this, unit, candidate, ...args);
        assert(!g.__forecastFault, `Forecast callback failed: ${g.__forecastFault}`);
        return value;
    } finally { scope = prior; }
};
g.__barrelForecastBoundary = (unit: any, context: any, before: any[], cleanup: any[]) => {
    if (!scope) return cleanup;
    try {
        assert.equal(context.decisionOrigin, "rollout", "A projected-turn scope must never change a live native root");
        g.__stats.boundaries++;
        const alternative = selectBarrelForecastIntent(unit, context, before, cleanup);
        if (alternative !== cleanup) {
            g.__stats.changed++;
            const key = unit.getTeam() === scope.rootTeam ? "ownFuture" : "enemyFuture";
            g.__stats[key]++;
            const intent = before.find((a: any) => ["move_unit", "wait_turn", "defend_turn"].includes(a.type)).type;
            g.__stats.intents[intent] = (g.__stats.intents[intent] ?? 0) + 1;
            if (g.__stats.witnesses.length < 8) g.__stats.witnesses.push({ ...scope, actor: unit.getName(), team: unit.getTeam(),
                lap: context.fightProperties.getCurrentLap(), before: structuredClone(before), cleanup: structuredClone(cleanup) });
        }
        return g.__mode === "forecast" ? alternative : cleanup;
    } catch (error) { g.__forecastFault = String(error); throw error; }
};

for await (const line of createInterface({ input: process.stdin })) {
    const { job, registrationSha256 } = JSON.parse(line);
    const team = (job.game < 2) === (job.game % 2 === 0) ? 2 : 1;
    const seed = permuteRankedDraftSeed(job.seed + 6 + Number(job.game >= 2));
    const modes = job.stage === "development" ? ["stock", "forecast", "accepted"] : ["stock", "observe", "forecast"];
    if (job.stage === "development" && (job.board + job.game) % 2) modes.reverse();
    const controls: any[] = []; let consumedHash: string | undefined;
    for (const mode of modes) {
        g.__mode = "stock";
        const built = buildChoice(job, "current", "current", team);
        if (job.draftConfigSha256) assert.equal(hash(built.drafted.config), job.draftConfigSha256[Number(job.game >= 2)]);
        const input = { config: built.opening.config, teams: built.opening.teams, terrain: built.opening.terrain, combatSeed: seed };
        const inputHash = hash(input);
        if (consumedHash) assert.equal(consumedHash, inputHash, "Reconstructed native setups differ across arms");
        consumedHash = inputHash;
        g.__mode = mode; g.__team = team; g.__acceptedCalls = 0; g.__forecastFault = undefined;
        g.__stats = { boundaries: 0, changed: 0, ownFuture: 0, enemyFuture: 0, intents: {}, witnesses: [] };
        const cpu = process.cpuUsage(), started = performance.now();
        const fought = fightNative(structuredClone(built.opening), seed);
        const used = process.cpuUsage(cpu);
        assert(!g.__forecastFault, `A callback error was swallowed: ${g.__forecastFault}`);
        assert.equal(fought.result.endReason, "elimination");
        const score = fought.result.winner === "draw" ? .5 : Number(fought.result.winner === (team === 2 ? "green" : "red"));
        const row = { ...job, mode, team, registrationSha256, inputSha256: inputHash,
            traceSha256: fought.traceSha256, score, winner: fought.result.winner,
            elapsedMs: performance.now() - started, cpuMs: (used.user + used.system) / 1000,
            forecast: g.__stats, acceptedModelCalls: g.__acceptedCalls,
            acceptedPairSha256: mode === "accepted" ? accepted.pairSha256 : undefined, quality: fought.quality };
        appendFileSync(output, JSON.stringify(row) + "\n");
        if (mode === "stock" || mode === "observe") controls.push(row);
    }
    if (controls.length === 2) assert.equal(controls[0].traceSha256, controls[1].traceSha256, "Observer changed complete default trace");
    console.log(JSON.stringify({ board: job.board, game: job.game, verified: true, rows: modes.length }));
}
